insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-grammar','___, proponuje pani najpierw przeprowadzić pilotaż.','["Jeśli dobrze rozumiem","Mimo punktu","Poza głosem"]',0,'Jeśli dobrze rozumiem нейтрально проверяет точность перефразирования.',0);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-grammar','Z jednej strony projekt ograniczy hałas, ___ może utrudnić dostawy.','["z drugiej strony","podsumowując że","co do tego"]',0,'Парная конструкция сопоставляет два аспекта.',1);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-grammar','Oddaję głos pani Nowak, a potem ___ do kwestii budżetu.','["wrócimy","odniesiemy głosem","podsumowując"]',0,'Wrócić do + dopełniacz обозначает возврат к вопросу.',2);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-grammar','___, uczestnicy poparli pilotaż, lecz nie uzgodnili terminu.','["Podsumowując","Innymi słowami do","Zabierając zgoda"]',0,'Podsumowując вводит сжатый итог с сохранением разногласия.',3);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-grammar','Составьте: Если я правильно понимаю, вы предлагаете изменить порядок обсуждения.','["Jeśli dobrze rozumiem, proponuje pan zmienić porządek dyskusji.","Jeśli dobrze rozumiem, pan propozycja zmienia porządkiem.","Dobrze rozumiejąc proponuje zmieniono dyskusję."]',0,'После proponować естественно употребляется infinitiv; формула смягчает проверку смысла.',4);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-grammar','Составьте: Подводя итог, мы согласны с целью, но способ остаётся спорным.','["Podsumowując, zgadzamy się co do celu, ale sposób pozostaje sporny.","Podsumowanie zgadzamy cel, natomiast sposób spór.","Podsumowując, zgoda celu mimo sposób spornego."]',0,'Zgadzać się co do + dopełniacz фиксирует область согласия; ale сохраняет контраст.',5);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Co robi moderator, gdy oddaje komuś głos?','["приглашает этого человека высказаться","завершает встречу","отменяет его аргумент"]',0,'Oddać głos — передать очередь говорящему.',0);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Która formuła neutralnie sprawdza cudzą intencję?','["Jeśli dobrze rozumiem…","To oczywisty błąd.","Nie ma o czym mówić."]',0,'Формула оставляет собеседнику возможность уточнить позицию.',1);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Punkt sporny to…','["вопрос, по которому сохраняется разногласие","готовый итог встречи","список участников"]',0,'Sporny указывает на отсутствие согласия.',2);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Jak uprzejmie wrócić do przerwanego wątku?','["Wróćmy do pytania o koszty.","Koszty nie istnieją.","Proszę już nie mówić."]',0,'Wróćmy do направляет разговор без оценки участника.',3);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Po co moderator parafrazuje wypowiedź?','["чтобы проверить смысл и сделать позицию понятной","чтобы изменить мнение автора","чтобы сократить число участников"]',0,'Перефразирование служит точности и общему пониманию.',4);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Z jednej strony…, z drugiej strony… służy do…','["сопоставления двух аспектов","цитирования закона","объявления перерыва"]',0,'Парный маркер организует сбалансированное сопоставление.',5);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Które podsumowanie zachowuje różnicę zdań?','["Zgadzamy się co do celu, ale termin pozostaje sporny.","Wszyscy myślą dokładnie tak samo.","Nie było żadnych argumentów."]',0,'Хороший итог различает согласованное и спорное.',6);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Dojść do głosu znaczy…','["получить возможность высказаться","потерять голос","прочитать итог"]',0,'Выражение относится к доступу к участию в разговоре.',7);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Moderator powinien przerwać wypowiedź, gdy…','["она явно выходит за регламент или тему","собеседник приводит данные","позиция отличается от его собственной"]',0,'Модерация регулирует процесс, а не взгляды.',8);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-quiz','Co oznacza osiągnąć porozumienie?','["выработать приемлемое согласованное решение","выиграть спор любой ценой","отложить все вопросы"]',0,'Porozumienie предполагает согласование позиций.',9);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-reading-check','Jaki był cel spotkania?','["Rozpoznanie potrzeb przed decyzją","Natychmiastowe głosowanie","Ocena wszystkich usług miasta"]',0,'Модератор обозначила исследовательскую цель встречи.',0);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-reading-check','Jak moderatorka ujęła dwie pierwsze pozycje?','["Jako potrzebę dostępu i pytanie o bezpieczną realizację","Jako konflikt studentów z seniorami","Jako spór o książki"]',0,'Перефразирование сохранило обе сути.',1);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-reading-check','Dlaczego moderatorka przerwała jeden wątek?','["Odszedł od ustalonego tematu","Nie zgadzała się z rozmówcą","Skończył się czas całej debaty"]',0,'Она вернула разговор к расписанию.',2);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-reading-check','Co wniosła wypowiedź seniorki?','["Połączyła godziny biblioteki z bezpiecznym powrotem","Zaproponowała zamknięcie klubu","Odrzuciła pilotaż"]',0,'Аргумент расширил понятие доступности.',3);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-reading-check','W jakiej sprawie osiągnięto porozumienie?','["Trzymiesięczny pilotaż przez dwa wieczory","Otwarcie codziennie przez całą noc","Rezygnacja ze zmian"]',0,'Это конкретный согласованный результат.',4);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2discussion-reading-check','Co pozostało punktem spornym?','["Finansowanie i dokładne godziny","Potrzeba biblioteki","Udział studentów"]',0,'Финальный итог явно называет нерешённые вопросы.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b2discussion-debata-o-bibliotece','b2-public-discussion','Debata o bibliotece otwartej wieczorem','Оригинальная запись общественного обсуждения с модерацией и итогом','B2',13,'🗣️','["W domu kultury odbyła się debata o wydłużeniu godzin pracy dzielnicowej biblioteki. Moderatorka, Marta Lis, przypomniała, że celem spotkania nie jest natychmiastowe głosowanie, lecz rozpoznanie potrzeb mieszkańców. Najpierw oddała głos studentom, seniorom i pracownikom biblioteki, a następnie poprosiła wszystkich, by trzymali się tematu dostępności po godzinie osiemnastej.","Przedstawicielka studentów argumentowała, że wieczorem trudno znaleźć spokojne miejsce do nauki. Kierownik biblioteki nie zakwestionował tej potrzeby, lecz zwrócił uwagę na koszty personelu i ochrony. Marta sparafrazowała obie wypowiedzi: jeśli dobrze rozumie, jedna strona podkreśla dostępność, a druga pyta o warunki bezpiecznej realizacji. Obaj rozmówcy potwierdzili, że takie ujęcie jest trafne.","Punktem spornym okazała się liczba dodatkowych wieczorów. Część mieszkańców chciała otwarcia przez cały tydzień, natomiast bibliotekarze proponowali dwa dni. Gdy dyskusja zeszła na ocenę innych usług miejskich, moderatorka uprzejmie ją przerwała: „Wróćmy do harmonogramu. Do szerszej polityki kulturalnej możemy odnieść się na kolejnym spotkaniu”. Dzięki temu także czekający seniorzy doszli do głosu.","Jedna z seniorek zauważyła, że późniejsze godziny pomogą nie tylko studentom. Klub czytelniczy mógłby spotykać się po pracy, pod warunkiem dobrego oświetlenia przystanku. Innymi słowy, dostępność budynku nie wystarcza bez bezpiecznego powrotu. Ten argument zmienił kierunek rozmowy: uczestnicy zaczęli rozważać pilotaż połączony z konsultacją dotyczącą transportu.","Podsumowując, co do potrzeby lepszego dostępu panowała zgoda. Uczestnicy osiągnęli porozumienie w sprawie trzymiesięcznego pilotażu w dwa wieczory tygodniowo. Nie uzgodnili jeszcze źródła finansowania ani ostatecznych godzin. Moderatorka zapisała oba punkty sporne i zapowiedziała, że następne spotkanie zacznie się od danych o kosztach oraz frekwencji."]','{"wydłużeniu":{"lemma":"wydłużenie","translation":"продлении","part_of_speech":"существительное"},"rozpoznanie":{"lemma":"rozpoznanie","translation":"выявление","part_of_speech":"существительное"},"dostępności":{"lemma":"dostępność","translation":"доступности","part_of_speech":"существительное"},"zakwestionował":{"lemma":"zakwestionować","translation":"оспорил","part_of_speech":"глагол"},"ochrony":{"lemma":"ochrona","translation":"охраны","part_of_speech":"существительное"},"sparafrazowała":{"lemma":"sparafrazować","translation":"перефразировала","part_of_speech":"глагол"},"ujęcie":{"lemma":"ujęcie","translation":"формулировка","part_of_speech":"существительное"},"trafne":{"lemma":"trafny","translation":"точное","part_of_speech":"прилагательное"},"spornym":{"lemma":"sporny","translation":"спорным","part_of_speech":"прилагательное"},"natomiast":{"lemma":"natomiast","translation":"тогда как","part_of_speech":"союз"},"harmonogramu":{"lemma":"harmonogram","translation":"расписания","part_of_speech":"существительное"},"odnieść":{"lemma":"odnieść się","translation":"обратиться","part_of_speech":"глагол"},"doszli":{"lemma":"dojść do głosu","translation":"получили слово","part_of_speech":"выражение"},"oświetlenia":{"lemma":"oświetlenie","translation":"освещения","part_of_speech":"существительное"},"wystarcza":{"lemma":"wystarczać","translation":"достаточно","part_of_speech":"глагол"},"rozważać":{"lemma":"rozważać","translation":"рассматривать","part_of_speech":"глагол"},"pilotaż":{"lemma":"pilotaż","translation":"пилотный проект","part_of_speech":"существительное"},"uzgodnili":{"lemma":"uzgodnić","translation":"согласовали","part_of_speech":"глагол"},"finansowania":{"lemma":"finansowanie","translation":"финансирования","part_of_speech":"существительное"},"frekwencji":{"lemma":"frekwencja","translation":"посещаемости","part_of_speech":"существительное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b2discussion-reading-check"}',44,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
